parameters.query:
WITH input AS (SELECT $1::uuid profile_id,$2::uuid session_id,$3::jsonb payload),
profile_guard AS (SELECT pg_advisory_xact_lock(hashtext(input.profile_id::text)) FROM input),
updated_profile AS (
 UPDATE profiles p SET name=COALESCE(input.payload->'fields'->>'name',p.name),age=COALESCE((input.payload->'fields'->>'age')::int,p.age),city=COALESCE(input.payload->'fields'->>'city',p.city),city_normalized=COALESCE(normalize_city_name(input.payload->'fields'->>'city'),p.city_normalized),district=COALESCE(input.payload->'fields'->>'district',p.district),height_cm=COALESCE((input.payload->'fields'->>'height_cm')::smallint,p.height_cm),weight_kg=COALESCE((input.payload->'fields'->>'weight_kg')::numeric,p.weight_kg),breast_size=COALESCE((input.payload->'fields'->>'breast_size')::numeric,p.breast_size),description=COALESCE(input.payload->'fields'->>'description',p.description),updated_at=now()
 FROM input,profile_guard WHERE p.id=input.profile_id RETURNING p.id
),
price_ops AS (
 SELECT upper(x.value->>'operation') operation,NULLIF(x.value->>'id','')::uuid id,x.value->>'service_name' service_name,(x.value->>'amount')::numeric amount,upper(COALESCE(x.value->>'currency','RUB')) currency,(x.value->>'duration_minutes')::int duration_minutes,x.value->>'description' description,x.ord
 FROM input,profile_guard CROSS JOIN LATERAL jsonb_array_elements(COALESCE(input.payload->'price_operations','[]'::jsonb)) WITH ORDINALITY AS x(value,ord)
),
price_append_unique AS (
 SELECT DISTINCT ON (lower(service_name),amount,currency,COALESCE(duration_minutes,-1),COALESCE(description,'')) * FROM price_ops WHERE operation='APPEND' ORDER BY lower(service_name),amount,currency,COALESCE(duration_minutes,-1),COALESCE(description,''),ord
),
price_append AS (
 SELECT p.*,row_number() OVER(ORDER BY p.ord)-1 append_offset FROM price_append_unique p,input WHERE NOT EXISTS(SELECT 1 FROM profile_prices e WHERE e.profile_id=input.profile_id AND e.is_active AND lower(e.service_name)=lower(p.service_name) AND e.amount=p.amount AND e.currency=p.currency AND e.duration_minutes IS NOT DISTINCT FROM p.duration_minutes AND e.description IS NOT DISTINCT FROM p.description)
),
price_max AS (SELECT COALESCE(MAX(e.position),-1) max_position FROM profile_prices e,input,profile_guard WHERE e.profile_id=input.profile_id),
price_inserted AS (
 INSERT INTO profile_prices(profile_id,service_name,amount,currency,duration_minutes,description,position) SELECT input.profile_id,p.service_name,p.amount,p.currency,p.duration_minutes,p.description,price_max.max_position+1+p.append_offset FROM input,price_append p,price_max ON CONFLICT DO NOTHING RETURNING id
),
price_updated AS (
 UPDATE profile_prices e SET service_name=p.service_name,amount=p.amount,currency=p.currency,duration_minutes=p.duration_minutes,description=p.description,updated_at=now() FROM price_ops p,input WHERE p.operation='UPDATE' AND p.id=e.id AND e.profile_id=input.profile_id RETURNING e.id
),
price_deleted AS (
 UPDATE profile_prices e SET is_active=false,updated_at=now() FROM price_ops p,input WHERE p.operation='DELETE' AND p.id=e.id AND e.profile_id=input.profile_id AND e.is_active RETURNING e.id
),
place_ops AS (
 SELECT upper(x.value->>'operation') operation,NULLIF(x.value->>'id','')::uuid id,upper(x.value->>'place_type') place_type,x.value->>'label' label,x.value->>'district' district,x.value->>'description' description,x.ord FROM input,profile_guard CROSS JOIN LATERAL jsonb_array_elements(COALESCE(input.payload->'meeting_place_operations','[]'::jsonb)) WITH ORDINALITY AS x(value,ord)
),
place_append_unique AS (
 SELECT DISTINCT ON (place_type,lower(label),COALESCE(district,''),COALESCE(description,'')) * FROM place_ops WHERE operation='APPEND' ORDER BY place_type,lower(label),COALESCE(district,''),COALESCE(description,''),ord
),
place_append AS (
 SELECT p.*,row_number() OVER(ORDER BY p.ord)-1 append_offset FROM place_append_unique p,input WHERE NOT EXISTS(SELECT 1 FROM profile_meeting_places e WHERE e.profile_id=input.profile_id AND e.is_active AND e.place_type=p.place_type AND lower(e.label)=lower(p.label) AND e.district IS NOT DISTINCT FROM p.district AND e.description IS NOT DISTINCT FROM p.description)
),
place_max AS (SELECT COALESCE(MAX(e.position),-1) max_position FROM profile_meeting_places e,input,profile_guard WHERE e.profile_id=input.profile_id),
place_inserted AS (
 INSERT INTO profile_meeting_places(profile_id,place_type,label,district,description,position) SELECT input.profile_id,p.place_type,p.label,p.district,p.description,place_max.max_position+1+p.append_offset FROM input,place_append p,place_max ON CONFLICT DO NOTHING RETURNING id
),
place_updated AS (
 UPDATE profile_meeting_places e SET place_type=p.place_type,label=p.label,district=p.district,description=p.description,updated_at=now() FROM place_ops p,input WHERE p.operation='UPDATE' AND p.id=e.id AND e.profile_id=input.profile_id RETURNING e.id
),
place_deleted AS (
 UPDATE profile_meeting_places e SET is_active=false,updated_at=now() FROM place_ops p,input WHERE p.operation='DELETE' AND p.id=e.id AND e.profile_id=input.profile_id AND e.is_active RETURNING e.id
),
context AS (
 UPDATE profile_ai_sessions s SET ai_context=COALESCE(s.ai_context,'{}'::jsonb)||jsonb_build_object('last_extraction',(SELECT payload FROM input)),updated_at=now() FROM input,profile_guard WHERE s.id=input.session_id AND s.profile_id=input.profile_id AND s.status='IN_PROGRESS' RETURNING s.id
)
SELECT (SELECT id::text FROM updated_profile) profile_id,(SELECT id::text FROM context) session_id,(SELECT count(*) FROM price_inserted) prices_appended,(SELECT count(*) FROM price_updated) prices_updated,(SELECT count(*) FROM price_deleted) prices_deleted,(SELECT count(*) FROM place_inserted) places_appended,(SELECT count(*) FROM place_updated) places_updated,(SELECT count(*) FROM place_deleted) places_deleted;
